import{_ as a,o as s,c as n,a6 as i}from"./chunks/framework.DL_pga9_.js";const g=JSON.parse('{"title":"References, Moves & Ownership","description":"","frontmatter":{},"headers":[],"relativePath":"guide/references-moves.md","filePath":"guide/references-moves.md","lastUpdated":1781686130000}'),t={name:"guide/references-moves.md"};function r(l,e,p,o,c,h){return s(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="references-moves-ownership" tabindex="-1">References, Moves &amp; Ownership <a class="header-anchor" href="#references-moves-ownership" aria-label="Permalink to “References, Moves &amp; Ownership”">​</a></h1><p>NG uses a <strong>value semantics</strong> model by default — variables are copied on assignment — with explicit <strong>references</strong> and <strong>moves</strong> for shared ownership and efficient transfers.</p><h2 id="value-semantics-default" tabindex="-1">Value Semantics (Default) <a class="header-anchor" href="#value-semantics-default" aria-label="Permalink to “Value Semantics (Default)”">​</a></h2><p>By default, bindings are independent copies:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val a = [1, 2, 3];</span></span>
<span class="line"><span>val b = a;        // b is a copy of a</span></span>
<span class="line"><span>b[0] = 99;</span></span>
<span class="line"><span>print(a[0]);      // 1 (a is unchanged)</span></span></code></pre></div><p>This applies to function arguments and return values too:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun modify(arr: [i32]) {</span></span>
<span class="line"><span>    arr[0] = 99;   // modifies the local copy only</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val arr = [1, 2, 3];</span></span>
<span class="line"><span>modify(arr);</span></span>
<span class="line"><span>print(arr[0]);     // 1 (unchanged)</span></span></code></pre></div><h2 id="reference-types-ref-t" tabindex="-1">Reference Types: <code>ref&lt;T&gt;</code> <a class="header-anchor" href="#reference-types-ref-t" aria-label="Permalink to “Reference Types: ref&lt;T&gt;”">​</a></h2><p>Create a reference to share access to a value:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val x = 42;</span></span>
<span class="line"><span>val r: ref&lt;i32&gt; = ref x;   // r refers to x</span></span>
<span class="line"><span>x = 43;</span></span>
<span class="line"><span>print(*r);                  // 43 (reads through the reference)</span></span></code></pre></div><h3 id="creating-references" tabindex="-1">Creating References <a class="header-anchor" href="#creating-references" aria-label="Permalink to “Creating References”">​</a></h3><p>Use the <code>ref</code> operator on a mutable place:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val x = 1;</span></span>
<span class="line"><span>val r = ref x;     // reference to x</span></span></code></pre></div><h3 id="reading-through-references" tabindex="-1">Reading Through References <a class="header-anchor" href="#reading-through-references" aria-label="Permalink to “Reading Through References”">​</a></h3><p>Dereference with <code>*</code>:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>print(*r);         // reads the value</span></span></code></pre></div><h3 id="writing-through-references" tabindex="-1">Writing Through References <a class="header-anchor" href="#writing-through-references" aria-label="Permalink to “Writing Through References”">​</a></h3><p>Use deref assignment <code>:=</code>:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*r := 10;</span><span>          // writes through the reference</span></span>
<span class="line"><span>print(x);          // 10</span></span></code></pre></div><h3 id="reference-parameters" tabindex="-1">Reference Parameters <a class="header-anchor" href="#reference-parameters" aria-label="Permalink to “Reference Parameters”">​</a></h3><p>Functions can accept references:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun swap&lt;T&gt;(a: ref&lt;T&gt;, b: ref&lt;T&gt;) {</span></span>
<span class="line"><span>    val tmp = move *a;</span></span>
<span class="line"><span>    *a := move *b;</span></span>
<span class="line"><span>    *b := move tmp;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val x = 1;</span></span>
<span class="line"><span>val y = 2;</span></span>
<span class="line"><span>swap(ref x, ref y);</span></span>
<span class="line"><span>print(x, y);       // 2, 1</span></span></code></pre></div><h2 id="move-semantics" tabindex="-1">Move Semantics <a class="header-anchor" href="#move-semantics" aria-label="Permalink to “Move Semantics”">​</a></h2><p><code>move</code> transfers ownership of a value, invalidating the original location:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val a = [1, 2, 3];</span></span>
<span class="line"><span>val b = move a;     // a is now invalid</span></span>
<span class="line"><span>// print(a[0]);</span><span>     // ERROR: use after move</span></span>
<span class="line"><span>print(b[0]);        // 1</span></span></code></pre></div><h3 id="move-dereference" tabindex="-1">Move Dereference <a class="header-anchor" href="#move-dereference" aria-label="Permalink to “Move Dereference”">​</a></h3><p>Combine <code>move</code> and <code>*</code> to move a value out of a reference:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun take&lt;T&gt;(dest: ref&lt;T&gt;, src: ref&lt;T&gt;) {</span></span>
<span class="line"><span>    *dest := move *src;</span><span>   // moves value from src into dest</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="runtime-move-checking" tabindex="-1">Runtime Move Checking <a class="header-anchor" href="#runtime-move-checking" aria-label="Permalink to “Runtime Move Checking”">​</a></h3><p>The interpreter tracks moved values at runtime and throws an error if you try to read a moved location before reassigning it:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val x = move a;    // a is now &quot;moved&quot;</span></span>
<span class="line"><span>// print(a);</span><span>       // Runtime error: use after move</span></span>
<span class="line"><span>a = [4, 5, 6];     // reassign — OK now</span></span>
<span class="line"><span>print(a);          // OK</span></span></code></pre></div><h2 id="references-to-object-properties" tabindex="-1">References to Object Properties <a class="header-anchor" href="#references-to-object-properties" aria-label="Permalink to “References to Object Properties”">​</a></h2><p>References can point to object fields:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Point { x: i32; y: i32; }</span></span>
<span class="line"><span>val p = new Point { x: 10, y: 20 };</span></span>
<span class="line"><span>val rx = ref p.x;</span></span>
<span class="line"><span>*rx := 99;</span></span>
<span class="line"><span>print(p.x);        // 99</span></span></code></pre></div><h2 id="partial-moves" tabindex="-1">Partial Moves <a class="header-anchor" href="#partial-moves" aria-label="Permalink to “Partial Moves”">​</a></h2><p>You can move individual fields from an object while leaving others accessible:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Person {</span></span>
<span class="line"><span>    name: string;</span></span>
<span class="line"><span>    age: i32;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val p = new Person { name: &quot;Alice&quot;, age: 30 };</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val name = move p.name;   // p.name is moved</span></span>
<span class="line"><span>// print(p.name);</span><span>         // ERROR: field was partially moved</span></span>
<span class="line"><span>print(p.age);             // OK: age is still accessible</span></span></code></pre></div><h3 id="restoration-after-partial-move" tabindex="-1">Restoration After Partial Move <a class="header-anchor" href="#restoration-after-partial-move" aria-label="Permalink to “Restoration After Partial Move”">​</a></h3><p>Writing to a partially-moved field restores full access:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>p.name = &quot;Bob&quot;;           // restores p.name</span></span>
<span class="line"><span>print(p.name);            // OK now</span></span></code></pre></div><h3 id="partial-move-tracking-in-objects" tabindex="-1">Partial Move Tracking in Objects <a class="header-anchor" href="#partial-move-tracking-in-objects" aria-label="Permalink to “Partial Move Tracking in Objects”">​</a></h3><p>The type checker tracks which fields have been partially moved and prevents reads from moved fields. This extends to nested objects and tuple fields:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val nested = new Wrapper { inner: new Inner { x: 1, y: 2 } };</span></span>
<span class="line"><span>val x = move nested.inner.x;</span></span>
<span class="line"><span>// print(nested.inner.x);</span><span> // ERROR: partially moved</span></span>
<span class="line"><span>print(nested.inner.y);    // OK</span></span></code></pre></div><h2 id="references-and-aliasing" tabindex="-1">References and Aliasing <a class="header-anchor" href="#references-and-aliasing" aria-label="Permalink to “References and Aliasing”">​</a></h2><h3 id="direct-ref-aliasing" tabindex="-1">Direct Ref Aliasing <a class="header-anchor" href="#direct-ref-aliasing" aria-label="Permalink to “Direct Ref Aliasing”">​</a></h3><p>A <code>ref</code> creates a borrow that remains active within its lexical scope. While a direct ref is alive, neither the original value nor the ref can be invalidated by moves:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val x = 1;</span></span>
<span class="line"><span>val r = ref x;</span></span>
<span class="line"><span>// val y = move x;</span><span>       // ERROR: can&#39;t move while ref is active</span></span>
<span class="line"><span>print(*r);                // OK — ref is still usable</span></span></code></pre></div><h3 id="ref-borrow-ends-at-scope-boundary" tabindex="-1">Ref Borrow Ends at Scope Boundary <a class="header-anchor" href="#ref-borrow-ends-at-scope-boundary" aria-label="Permalink to “Ref Borrow Ends at Scope Boundary”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val x = 1;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    val r = ref x;        // borrow starts</span></span>
<span class="line"><span>    print(*r);</span></span>
<span class="line"><span>}                         // borrow ends</span></span>
<span class="line"><span>val y = move x;           // OK — ref is gone</span></span></code></pre></div><h2 id="heap-allocated-objects-new" tabindex="-1">Heap-Allocated Objects (<code>new</code>) <a class="header-anchor" href="#heap-allocated-objects-new" aria-label="Permalink to “Heap-Allocated Objects (new)”">​</a></h2><p>Objects created with <code>new</code> are heap-allocated and alias by reference:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val a = new Point { x: 1, y: 2 };</span></span>
<span class="line"><span>val b = a;                // b aliases the same heap object</span></span>
<span class="line"><span>a.x = 10;</span></span>
<span class="line"><span>print(b.x);               // 10 (shared)</span></span></code></pre></div><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to “What&#39;s Next?”">​</a></h2><p>Continue to <a href="./traits">Traits</a> to learn about NG&#39;s trait system for abstraction and polymorphism.</p><blockquote><p><strong>Try it:</strong> <code>example/22.ref_move_swap.ng</code> — Reference swap <strong>Try it:</strong> <code>example/23.ref_places.ng</code> — References to places <strong>Try it:</strong> <code>example/24.move_value_semantics.ng</code> — Move semantics <strong>Try it:</strong> <code>example/50.partial_move.ng</code> — Partial moves <strong>Try it:</strong> <code>example/51.partial_move_drop.ng</code> — Partial moves with Drop</p></blockquote>`,55)])])}const b=a(t,[["render",r]]);export{g as __pageData,b as default};
